function createFakeElement(tagName) {
  let innerHTML = "";
  const listeners = new Map();
  return {
    tagName,
    style: {},
    dataset: {},
    children: [],
    textContent: "",
    className: "",
    value: "",
    autocomplete: "",
    spellcheck: false,
    type: "",
    focused: false,
    appendChild(child) {
      this.children.push(child);
      return child;
    },
    addEventListener(type, handler) {
      const arr = listeners.get(type) || [];
      arr.push(handler);
      listeners.set(type, arr);
    },
    dispatch(type, event = {}) {
      const arr = listeners.get(type) || [];
      for (const handler of arr) handler(event);
    },
    focus() {
      this.focused = true;
    },
    blur() {
      this.focused = false;
    },
    get innerHTML() {
      return innerHTML;
    },
    set innerHTML(value) {
      innerHTML = value;
      this.children.length = 0;
    },
  };
}

