+    const glow = pin.set ? 1 : charge;
+
+    ctx.save();
+    ctx.translate(px, py);
+    ctx.rotate(pin.angle + Math.PI / 2);
+    ctx.fillStyle = pin.set ? "rgba(84,224,154,.95)" : `rgba(255,255,255,${0.18 + glow * 0.55})`;
