+  ctx.fill();
+  ctx.strokeStyle = s.solved ? "rgba(84,224,154,.9)" : "rgba(255,255,255,.14)";
+  ctx.lineWidth = 3;
+  ctx.beginPath();
+  ctx.arc(0, 0, r * 0.38, 0, TAU);
+  ctx.stroke();
+  ctx.fillStyle = s.solved ? "rgba(84,224,154,.95)" : "rgba(255,255,255,.68)";
+  ctx.font = "900 16px ui-sans-serif, system-ui";
