    boxShadow: "0 0 12px white",
  });
  const tensionLabel = make("div", "", "TORQ");
  setStyles(tensionLabel, {
    position: "absolute",
    left: "0",
    right: "0",
    bottom: "11px",
    textAlign: "center",
    fontSize: "10px",
    fontWeight: "900",
    color: "rgba(255,255,255,.72)",
    letterSpacing: ".12em",
  });
  tension.append(tensionFill, tensionNeedle, tensionLabel);
  stage.append(canvas, tension);
  card.appendChild(stage);

  const bottom = make("div", "");
  setStyles(bottom, { padding: "0 16px 16px", display: "grid", gap: "10px" });
  const meter = make("div", "");
  setStyles(meter, {
    height: "8px",
    borderRadius: "999px",
    background: "rgba(255,255,255,.08)",
    overflow: "hidden",
    border: "1px solid rgba(255,255,255,.16)",
  });
  const progress = make("i", "");
  setStyles(progress, {
    display: "block",
    width: "0%",
    height: "100%",
    background: "linear-gradient(90deg, #54e09a, #77b4d6)",
  });
  meter.appendChild(progress);
  const readout = make("div", "");
  setStyles(readout, {
    display: "flex",
    justifyContent: "space-between",
    gap: "12px",
    color: "#9ba9be",
    fontSize: "12px",
    fontWeight: "750",
  });
  const status = make("span", "", game.state.status);
  const count = make("span", "", `0/${game.pinCount}`);
  readout.append(status, count);
  const toast = make("div", "", game.state.message);
  setStyles(toast, { minHeight: "34px", fontSize: "12px", lineHeight: "1.35", color: "#eef4ff", opacity: ".9" });
  bottom.append(meter, readout, toast);
  card.appendChild(bottom);
  inner.appendChild(card);

  const ctx = canvas.getContext("2d");
  const els = { progress, tensionFill, tensionNeedle, status, count, toast };
  let tensionPointer = null;
  let pickPointer = null;
  let raf = 0;
  let lastTime = performance.now();
  let wasSolved = false;

  function finish(success, reason) {
    window.dispatchEvent(new CustomEvent("ui:lockPickingFinished", {
      detail: {
        success,
        reason,
        pins: game.pinCount,
        difficulty: game.difficulty.id,
      },
    }));
  }

  function frame(now) {
    if (panel.style.display === "none") return;
    const dt = Math.min(40, now - lastTime);
    lastTime = now;
    game.tick(dt);
    if (game.state.solved && !wasSolved) {
      wasSolved = true;
      vibrate([25, 45, 25, 45, 60]);
      finish(true, "unlocked");
    }
    updateHud(game, els);
    drawLock(game, canvas, ctx);
    raf = requestAnimationFrame(frame);
  }

  function resetGame() {
    game.reset();
    wasSolved = false;
    updateHud(game, els);
    drawLock(game, canvas, ctx);
  }

  tension.addEventListener("pointerdown", (e) => {
    tensionPointer = e.pointerId;
    tension.setPointerCapture?.(e.pointerId);
    updateTensionFromPointer(game, tension, e);
  });
  tension.addEventListener("pointermove", (e) => {
    if (tensionPointer === e.pointerId) updateTensionFromPointer(game, tension, e);
  });
  tension.addEventListener("pointerup", (e) => {
    if (tensionPointer === e.pointerId) {
      tensionPointer = null;
      game.state.tension = 0;
    }
  });
  tension.addEventListener("pointercancel", (e) => {
    if (tensionPointer === e.pointerId) {
      tensionPointer = null;
      game.state.tension = 0;
    }
  });
  canvas.addEventListener("pointerdown", (e) => {
    pickPointer = e.pointerId;
    canvas.setPointerCapture?.(e.pointerId);
    game.state.pickActive = true;
    updatePickFromPointer(game, canvas, e);
  });
  canvas.addEventListener("pointermove", (e) => {
    if (pickPointer === e.pointerId) updatePickFromPointer(game, canvas, e);
  });
  canvas.addEventListener("pointerup", (e) => {
    if (pickPointer === e.pointerId) {
      pickPointer = null;
      game.state.pickActive = false;
    }
  });
  canvas.addEventListener("pointercancel", (e) => {
    if (pickPointer === e.pointerId) {
      pickPointer = null;
      game.state.pickActive = false;
    }
  });
  reset.addEventListener("click", resetGame);

  function onKeyDown(e) {
    if (panel.style.display !== "block") return;
    if (e.key === "Escape") {
      finish(false, "cancelled");
      panel.style.display = "none";
      e.preventDefault();
    }
  }
  window.addEventListener("keydown", onKeyDown);

  function cleanup() {
    if (raf) cancelAnimationFrame(raf);
    window.removeEventListener("keydown", onKeyDown);
  }
  panel._lockPickingCleanup = cleanup;

  fitCanvas(canvas, ctx);
  window.addEventListener("resize", () => fitCanvas(canvas, ctx), { once: true });
  updateHud(game, els);
  drawLock(game, canvas, ctx);
  raf = requestAnimationFrame(frame);
}

